CREATE TYPE "OAuthProvider" AS ENUM ('google', 'slack');
CREATE TABLE "User" ("id" TEXT NOT NULL, "googleId" TEXT, "email" TEXT NOT NULL, "name" TEXT NOT NULL, "avatarUrl" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "userId" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OAuthState" ("id" TEXT NOT NULL, "stateHash" TEXT NOT NULL, "provider" "OAuthProvider" NOT NULL, "userId" TEXT, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "OAuthState_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SlackConnection" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "teamId" TEXT NOT NULL, "teamName" TEXT, "encryptedAccessToken" TEXT NOT NULL, "botUserId" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SlackConnection_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EmailIndexOutbox" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "emailId" TEXT NOT NULL, "operation" TEXT NOT NULL DEFAULT 'upsert', "attempts" INTEGER NOT NULL DEFAULT 0, "lastError" TEXT, "processedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "EmailIndexOutbox_pkey" PRIMARY KEY ("id"));
ALTER TABLE "Sender" ADD COLUMN "ownerId" TEXT;
ALTER TABLE "Schedule" ADD COLUMN "ownerId" TEXT;
ALTER TABLE "Email" ADD COLUMN "ownerId" TEXT;
INSERT INTO "User" ("id", "email", "name") SELECT 'legacy-owner', 'legacy-owner@local.invalid', 'Legacy owner' WHERE EXISTS (SELECT 1 FROM "Sender");
UPDATE "Sender" SET "ownerId" = 'legacy-owner' WHERE "ownerId" IS NULL;
UPDATE "Schedule" s SET "ownerId" = se."ownerId" FROM "Sender" se WHERE s."senderId" = se."id" AND s."ownerId" IS NULL;
UPDATE "Email" e SET "ownerId" = se."ownerId" FROM "Sender" se WHERE e."senderId" = se."id" AND e."ownerId" IS NULL;
ALTER TABLE "Sender" ALTER COLUMN "ownerId" SET NOT NULL;
ALTER TABLE "Schedule" ALTER COLUMN "ownerId" SET NOT NULL;
ALTER TABLE "Email" ALTER COLUMN "ownerId" SET NOT NULL;
CREATE UNIQUE INDEX "User_googleId_key" ON "User"("googleId"); CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash"); CREATE UNIQUE INDEX "OAuthState_stateHash_key" ON "OAuthState"("stateHash"); CREATE UNIQUE INDEX "SlackConnection_userId_teamId_key" ON "SlackConnection"("userId", "teamId");
CREATE INDEX "Session_userId_expiresAt_idx" ON "Session"("userId", "expiresAt"); CREATE INDEX "OAuthState_provider_expiresAt_idx" ON "OAuthState"("provider", "expiresAt"); CREATE INDEX "SlackConnection_userId_active_idx" ON "SlackConnection"("userId", "active"); CREATE INDEX "EmailIndexOutbox_processedAt_createdAt_idx" ON "EmailIndexOutbox"("processedAt", "createdAt"); CREATE INDEX "Email_ownerId_status_scheduledTime_idx" ON "Email"("ownerId", "status", "scheduledTime");
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "OAuthState" ADD CONSTRAINT "OAuthState_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "SlackConnection" ADD CONSTRAINT "SlackConnection_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "EmailIndexOutbox" ADD CONSTRAINT "EmailIndexOutbox_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Sender" ADD CONSTRAINT "Sender_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Schedule" ADD CONSTRAINT "Schedule_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Email" ADD CONSTRAINT "Email_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
